//! Required HR align DOMString reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><hr id=para align=MiXeD><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://hr-align.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn hr_align_canonical_accessor_descriptor_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),P=HTMLHRElement.prototype,a=Object.getOwnPropertyDescriptor(P,'align');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get align'||a.set.name!=='set align'||Object.hasOwn(x,'align')||x.align!=='MiXeD'||x.textContent!=='')throw 'canonical horizontal rule align accessor';"#);}
#[test]
fn hr_align_native_domstring_aliases_old_values_and_absent_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.align='A\ud800Z';var records=watch.takeRecords();if(x.align!=='A\ud800Z'||attr.value!==x.align||x.getAttributeNode('align')!==attr||records.length!==1||records[0].attributeName!=='align'||records[0].oldValue!=='MiXeD'||x.textContent!=='')throw 'exact horizontal rule align transaction';attr.nodeValue='unrestricted';if(x.align!=='unrestricted')throw 'ordinary string reflection';x.removeAttribute('align');if(x.align!==''||attr.ownerElement!==null||attr.value!=='unrestricted')throw 'removed align default';x.align=null;if(x.align!=='null'||document.getElementById('neighbor').value!=='seed')throw 'null DOMString conversion';"#);}
#[test]
fn hr_align_inert_exact_namespace_once_conversion_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:hr');if(!(x instanceof HTMLHRElement)||x.align!=='')throw 'inert horizontal rule align default';var calls=0;x.align={toString:function(){calls++;x.setAttribute('align','author');return 'R\udfffZ';}};if(calls!==1||x.align!=='R\udfffZ'||x.getAttribute('align')!==x.align)throw 'once exact conversion';x.setAttributeNS('urn:foreign','align','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.align!=='R\udfffZ')throw 'exact null namespace align';var clone=x.cloneNode(false);if(clone.align!==x.align)throw 'namespace copy';x.removeAttributeNS('urn:foreign','align');x.removeAttributeNS(null,'ALIGN');var copy=document.importNode(x,false);if(copy.align!==x.align||copy.ownerDocument!==document||clone.getAttributeNode('align')===x.getAttributeNode('align'))throw 'actual copies';clone.align='independent';if(x.align!=='R\udfffZ'||copy.align!=='R\udfffZ')throw 'independent copied align';"#);}

#[test]
fn hr_align_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),old=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.align={toString:function(){calls++;x.removeAttribute('align');x.setAttribute('align','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('align'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='MiXeD'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.align={toString:function(){x.setAttribute('align','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.align!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.align=Symbol('div');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.align!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.align=value;if(x.align!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='')throw 'metadata leaves displayed text';"#);
}

#[test]
fn hr_align_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),C=HTMLHRElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'align'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('h1'),document.createElement('div'),document.createElement('legend'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','hr'),new Document().createElementNS('http://www.w3.org/1999/xhtml','HR')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'align',{value:'author',writable:true,configurable:true});if(x.align!=='author'||a.get.call(x)!=='MiXeD')throw 'canonical authority';a.set.call(x,'canonical');if(x.align!=='author'||x.getAttribute('align')!=='canonical')throw 'borrowed real setter';delete x.align;if(x.align!=='canonical'||Object.hasOwn(x,'align'))throw 'restored inherited reflection';delete window.HTMLHRElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn hr_align_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');x.setAttribute('align','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('align');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.align!=='R\ud800'+writer||x.getAttributeNode('align')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','align','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.align!=='R\ud800textContent'||x.getAttributeNodeNS(null,'align')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'align','no date parsing');if(x.align!=='no date parsing'||a.value!==x.align)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.align!==x.align||copy.getAttributeNode('align')===a)throw 'independent clone';x.removeAttributeNS(null,'align');if(x.align!==''||a.ownerElement!==null||copy.align!=='no date parsing')throw 'removed actual default';"#);}
}

#[test]
fn hr_align_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('align'),first=x.firstChild,list=x.childNodes,C=HTMLHRElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.align!=='MiXeD'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native data adoption';x.align='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.align!=='A\udfffZ'||x.getAttributeNode('align')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!==''||attr.value!==x.align)throw 'reconnected data source';"#);
}

#[test]
fn hr_align_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLHRElement,a=Object.getOwnPropertyDescriptor(C.prototype,'align'),calls=0;if(C===HTMLHRElement||a.get.call(x)!=='MiXeD')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-hr-align.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://hr-align.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn hr_align_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.align='Long canonical \ud800 HR alignment replacement';",r"x.setAttribute('align','Long canonical \ud800 HR alignment replacement');",r"attr.value='Long canonical \ud800 HR alignment replacement';",r"attr.nodeValue='Long canonical \ud800 HR alignment replacement';",r"attr.textContent='Long canonical \ud800 HR alignment replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');x.setAttribute('align','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='MiXeD'||x.align!=='MiXeD'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.align!=='Long canonical \ud800 HR alignment replacement'||records.length!==1||records[0].oldValue!=='MiXeD'||records[0].attributeName!=='align'||x.getAttributeNode('align')!==attr)throw 'fresh value writer recovery';");
 }}}
}

#[test]
fn hr_align_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');data.align='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('para').align='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("para")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hr_align_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hr_align_get(object).is_ok());}}
}

#[test]
fn hr_align_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["hr"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('para');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.align='exact';");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.align='exact';");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('align');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('align')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('align')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.align!==source.align||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn hr_align_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["hr"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.align='exact';var first=source.firstChild,attr=source.getAttributeNode('align');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('align')!==attr||source.align!=='exact'||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn hr_align_void_native_copies_import_and_template_keep_actual_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para');x.align='A\ud800Z';var attr=x.getAttributeNode('align'),copy=x.cloneNode(true),a=copy.getAttributeNode('align');if(!(copy instanceof HTMLHRElement)||copy.align!==x.align||copy.firstChild!==null||x.firstChild!==null||copy.textContent!==''||a===attr)throw 'actual void deep clone';copy.align='independent';if(x.align!=='A\ud800Z'||attr.value!==x.align)throw 'independent void metadata';var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','t:hr');source.align='I\udfffZ';var imported=document.importNode(source,true);document.body.appendChild(imported);if(!(imported instanceof HTMLHRElement)||imported.align!==source.align||imported.firstChild!==null||imported.getAttributeNode('align')===source.getAttributeNode('align')||source.ownerDocument!==doc)throw 'actual void import';var leaf=imported.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.align!==imported.align||leaf.firstChild!==null||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument)throw 'actual void template parking';"#);
}

#[test]
fn hr_align_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="hr"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('para'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','hr'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.align!=='MiXeD')throw 'active content copy guard';");}
}

