fn hr_align_interface_descriptors_and_bare_constructor_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLHRElement,P=C.prototype,g=Object.getOwnPropertyDescriptor(window,'HTMLHRElement'),a=Object.getOwnPropertyDescriptor(C,'prototype'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag);if(g.enumerable||!g.writable||!g.configurable||g.value!==C||a.writable||a.enumerable||a.configurable||a.value!==P||tag.value!=='HTMLHRElement'||tag.writable||tag.enumerable||!tag.configurable||Object.getPrototypeOf(C)!==HTMLElement||C.name!=='HTMLHRElement')throw 'horizontal rule canonical descriptors';var caught=false;try{C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal bare horizontal rule constructor';");}
#[test]
fn hr_align_exact_factories_and_saved_deleted_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLHRElement,P=C.prototype,doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:hr');if(!(x instanceof C)||x.align!==''||doc.createElementNS('http://www.w3.org/1999/xhtml','HR') instanceof C||document.createElementNS('urn:foreign','hr') instanceof C)throw 'exact horizontal rule factory';delete window.HTMLHRElement;var y=document.createElement('HR');y.align='metadata';var copy=y.cloneNode(false);if(!(y instanceof C)||!(copy instanceof C)||Object.getPrototypeOf(y)!==P||y.localName!=='hr'||y.firstChild!==null||copy.align!=='metadata'||copy.getAttributeNode('align')===y.getAttributeNode('align'))throw 'saved horizontal rule canonical factory';");}
